167	pub(crate) fn utf8_width(source: &[u8], offset: usize) -> Option<usize> {
168	    let first = *source.get(offset)?;
169	    let width = match first { 0xc2..=0xdf => 2, 0xe0..=0xef => 3, 0xf0..=0xf4 => 4, _ => return None };
170	    let end = offset.checked_add(width)?; let bytes = source.get(offset..end)?; let second = bytes[1];
171	    if second & 0xc0 != 0x80 || (first == 0xe0 && second < 0xa0) || (first == 0xed && second >= 0xa0) ||
172	       (first == 0xf0 && second < 0x90) || (first == 0xf4 && second >= 0x90) || bytes[2..].iter().any(|b| b & 0xc0 != 0x80) { return None; }
173	    Some(width)
174	}
