176	pub(crate) fn decode_string(raw: &[u8]) -> Option<Vec<u8>> {
177	    let mut out = Vec::new(); out.try_reserve(raw.len().min(MAX_STRING_BYTES)).ok()?;
178	    let mut i = 0;
179	    while i < raw.len() {
180	        if raw[i] != b'\\' {
181	            if raw[i] < 0x80 {
182	                if out.len()==MAX_STRING_BYTES{return None;}
183	                out.push(raw[i]); i += 1;
184	            }
185	            else {
186	                let n = utf8_width(raw, i)?;
187	                if out.len().checked_add(n)? > MAX_STRING_BYTES{return None;}
188	                out.extend_from_slice(raw.get(i..i.checked_add(n)?)?); i += n;
189	            }
190	        } else {
191	            i += 1; let esc = *raw.get(i)?; i += 1;
192	            let cp = match esc {
193	                b'"' => 34, b'\\' => 92, b'/' => 47, b'b' => 8, b'f' => 12, b'n' => 10, b'r' => 13, b't' => 9,
194	                b'u' => {
195	                    let mut cp = read_hex4(raw, &mut i)?;
196	                    if (0xd800..=0xdbff).contains(&cp) {
197	                        if raw.get(i..i.checked_add(2)?)? != b"\\u" { return None; } i += 2;
198	                        let low = read_hex4(raw, &mut i)?; if !(0xdc00..=0xdfff).contains(&low) { return None; }
199	                        cp = 0x10000 + ((cp - 0xd800) << 10) + low - 0xdc00;
200	                    }
201	                    cp
202	                }
203	                _ => return None,
204	            };
205	            let ch = char::from_u32(cp)?; let mut buf = [0; 4]; let bytes=ch.encode_utf8(&mut buf).as_bytes();
206	            if out.len().checked_add(bytes.len())? > MAX_STRING_BYTES{return None;}
207	            out.extend_from_slice(bytes);
208	        }
209	    }
210	    Some(out)
211	}
