213	/// Decodes raw JSON string contents into caller storage. `encoded` excludes the quotes.
214	/// The returned byte count is set only on success; malformed data and insufficient
215	/// output capacity both return `None`, matching the legacy boolean contract.
216	pub fn string_copy(encoded: &[u8], output: &mut [u8]) -> Option<usize> {
217	    let mut input=0usize; let mut written=0usize;
218	    while input<encoded.len() {
219	        let byte=encoded[input];
220	        if byte!=b'\\' {
221	            if byte<0x80 {
222	                if byte<0x20{return None;}
223	                *output.get_mut(written)?=byte; written+=1; input+=1;
224	            } else {
225	                let width=utf8_width(encoded,input)?;
226	                let end=input.checked_add(width)?; let target=output.get_mut(written..written.checked_add(width)?)?;
227	                target.copy_from_slice(encoded.get(input..end)?); written+=width; input=end;
228	            }
229	        } else {
230	            input+=1; let escape=*encoded.get(input)?; input+=1;
231	            let codepoint=match escape {
232	                b'"'=>34,b'\\'=>92,b'/'=>47,b'b'=>8,b'f'=>12,b'n'=>10,b'r'=>13,b't'=>9,
233	                b'u'=>{
234	                    let mut high=read_hex4(encoded,&mut input)?;
235	                    if (0xd800..=0xdbff).contains(&high) {
236	                        if encoded.get(input..input.checked_add(2)?)?!=b"\\u"{return None;} input+=2;
237	                        let low=read_hex4(encoded,&mut input)?; if !(0xdc00..=0xdfff).contains(&low){return None;}
238	                        high=0x10000+((high-0xd800)<<10)+low-0xdc00;
239	                    } else if (0xdc00..=0xdfff).contains(&high){return None;}
240	                    high
241	                }
242	                _=>return None,
243	            };
244	            let character=char::from_u32(codepoint)?; let mut scratch=[0;4]; let bytes=character.encode_utf8(&mut scratch).as_bytes();
245	            let end=written.checked_add(bytes.len())?; output.get_mut(written..end)?.copy_from_slice(bytes); written=end;
246	        }
247	    }
248	    Some(written)
249	}
250	fn read_hex4(raw: &[u8], i: &mut usize) -> Option<u32> {
251	    let end = i.checked_add(4)?; let mut value = 0;
252	    for byte in raw.get(*i..end)? { value = value * 16 + match byte { b'0'..=b'9' => u32::from(byte-b'0'), b'a'..=b'f' => u32::from(byte-b'a')+10, b'A'..=b'F' => u32::from(byte-b'A')+10, _ => return None }; }
253	    *i = end; Some(value)
254	}
