257	    let mut reader = Reader::new(source, None); reader.cursor = span.start; reader.space()?;
258	    if reader.source.get(reader.cursor) != Some(&b'{') { return Err(reader.failure(Error::InvalidSchema, span.start)); }
259	    reader.cursor += 1; reader.space()?; let mut fields = Vec::new();
260	    if reader.source.get(reader.cursor) == Some(&b'}') {
261	        reader.cursor += 1;
262	        if reader.cursor != span.end { return Err(reader.failure(Error::MalformedJson, reader.cursor)); }
