267	        if fields.iter().any(|field: &Field| field.key == key) { return Err(reader.failure(Error::Duplicate, key_offset)); }
268	        reader.space()?; if reader.source.get(reader.cursor) != Some(&b':') { return Err(reader.failure(Error::MalformedJson, reader.cursor)); }
269	        reader.cursor += 1; reader.space()?; let start = reader.cursor;
270	        if fields.len() == MAX_FIELDS { return Err(reader.failure(Error::Limit, start)); }
271	        reader.scan(1)?; let end = reader.cursor;
272	        fields.try_reserve(1).map_err(|_| reader.failure(Error::Limit, start))?;
273	        fields.push(Field { key, value: Span { start, end } });
