281	pub(crate) fn array_spans(source: &[u8], span: Span, limit: usize) -> Result<Vec<Span>, DecodeFailure> {
282	    let mut reader = Reader::new(source, None); reader.cursor = span.start; reader.space()?;
283	    if reader.source.get(reader.cursor) != Some(&b'[') { return Err(reader.failure(Error::InvalidSchema, span.start)); }
284	    reader.cursor += 1; reader.space()?; let mut spans = Vec::new();
285	    if reader.source.get(reader.cursor) == Some(&b']') { reader.cursor += 1; }
286	    else { loop {
287	        if spans.len() == limit { return Err(reader.failure(Error::Limit, reader.cursor)); }
288	        let start = reader.cursor; reader.scan(1)?; spans.try_reserve(1).map_err(|_| reader.failure(Error::Limit, start))?;
289	        spans.push(Span { start, end: reader.cursor }); reader.space()?;
290	        match reader.source.get(reader.cursor) { Some(b']') => { reader.cursor += 1; break; }, Some(b',') => { reader.cursor += 1; reader.space()?; }, _ => return Err(reader.failure(Error::MalformedJson, reader.cursor)) }
291	    } }
292	    if reader.cursor != span.end { return Err(reader.failure(Error::MalformedJson, reader.cursor)); }
293	    Ok(spans)
294	}
