168	pub fn classify(source:&[u8]) -> Result<bool> { classify_cancellable(source,None::<fn()->bool>) }
169	pub fn classify_cancellable<F>(source:&[u8],cancel:Option<F>) -> Result<bool>
170	where F:FnMut()->bool {
171	    if source.len()>MAX_SOURCE_BYTES { return Err(at(Error::Limit,0)); }
172	    let mut callback=cancel;
173	    let cancel_ref=callback.as_mut().map(|f|f as &mut dyn FnMut()->bool);
174	    let mut reader=Reader::new(source,cancel_ref); reader.scan(0)?; let end=reader.cursor; reader.space()?;
175	    if reader.cursor!=source.len() { return Err(reader.failure(Error::MalformedJson,reader.cursor)); }
176	    let root=object_fields(source,Span{start:0,end})?;
177	    let Some(s)=field(&root,b"schema") else{return Ok(false)};
178	    let value=string(source,s.value)?; if value!=b"vexel.animation" {return Ok(false)}
179	    let Some(v)=field(&root,b"version") else{return Ok(false)};
180	    Ok(uint(source,v.value).is_ok_and(|n|n==1))
181	}
