183	fn validate_context(context:&TimelineContext)->Result<()> {
184	    if context.scene_ids.len()>MAX_SCENE_IDS||context.assets.len()>MAX_ASSETS{return Err(at(Error::Limit,0));}
185	    for (i,id) in context.scene_ids.iter().enumerate(){
186	        if id.is_empty()||id.len()>256{return Err(at(Error::InvalidArgument,0));}
187	        if i>0 {match context.scene_ids[i-1].cmp(id){std::cmp::Ordering::Equal=>return Err(at(Error::Duplicate,0)),std::cmp::Ordering::Greater=>return Err(at(Error::InvalidArgument,0)),_=>()}}
188	    }
189	    for (i,a) in context.assets.iter().enumerate(){
190	        if !valid_asset_name(&a.name)||!valid_media_type(&a.media_type){return Err(at(Error::InvalidArgument,0));}
191	        if context.assets[..i].iter().any(|prior|prior.name==a.name){return Err(at(Error::Duplicate,0));}
192	    }
193	    Ok(())
194	}
195	fn valid_asset_name(s:&[u8])->bool { !s.is_empty()&&s.len()<=MAX_ASSET_NAME_BYTES&&s!=b"."&&s!=b".."&&s.iter().all(|b|b.is_ascii_alphanumeric()||matches!(*b,b'.'|b'_'|b'-')) }
196	fn valid_media_type(s:&[u8])->bool { s.len()>=3&&s.len()<=MAX_MEDIA_TYPE_BYTES&&s.iter().filter(|b|**b==b'/').count()==1&&s.iter().all(|b|(0x21..=0x7e).contains(b))&&s[0]!=b'/'&&s[s.len()-1]!=b'/' }
197	fn valid_track_id(s:&[u8])->bool { !s.is_empty()&&s.len()<=128&&s.iter().all(|b|b.is_ascii_alphanumeric()||matches!(*b,b'_'|b'-')) }
198	fn validate_property(source:&[u8],fields:&[Field],span:Span)->Result<()> {
199	    let prop_f=required(fields,b"property").ok_or_else(||at(Error::InvalidValue,span.start))?;
200	    let type_f=required(fields,b"value_type").ok_or_else(||at(Error::InvalidValue,span.start))?;
201	    let interp_f=required(fields,b"interpolation").ok_or_else(||at(Error::InvalidValue,span.start))?;
202	    let prop=string(source,prop_f.value).map_err(|_|at(Error::InvalidValue,span.start))?;
203	    let kind=string(source,type_f.value).map_err(|_|at(Error::InvalidValue,span.start))?;
204	    let interpolation=string(source,interp_f.value).map_err(|_|at(Error::InvalidValue,span.start))?;
205	    if prop.is_empty() || ![b"step".as_slice(),b"linear",b"cubic"].contains(&interpolation.as_slice()) ||
206	       ![b"scalar".as_slice(),b"transform2d",b"rgba",b"boolean"].contains(&kind.as_slice()) {
207	        return Err(at(Error::InvalidValue,span.start));
208	    }
209	    let scalar=[b"x".as_slice(),b"y",b"width",b"height",b"cx",b"cy",b"r",b"rx",b"ry",b"opacity",b"fill-opacity",b"stroke-opacity",b"stroke-width",b"stroke-dashoffset"].contains(&prop.as_slice())&&kind==b"scalar";
210	    let match_ok=scalar||([b"fill".as_slice(),b"stroke"].contains(&prop.as_slice())&&kind==b"rgba")||(prop==b"transform"&&kind==b"transform2d")||(prop==b"visibility"&&kind==b"boolean");
211	    if !match_ok {return Err(at(Error::InvalidValue,prop_f.value.start));}
212	    if kind==b"boolean"&&interpolation!=b"step" {return Err(at(Error::InvalidValue,interp_f.value.start));}
213	    Ok(())
214	}
215	fn validate_typed_value(source:&[u8],span:Span,kind:&[u8])->Result<()> {
216	    if kind==b"boolean" {boolean(source,span).map(|_|())?;return Ok(())}
217	    if kind==b"scalar" {number(source,span).map(|_|())?;return Ok(())}
218	    if kind==b"transform2d"||kind==b"rgba" {
219	        let spans=array_spans(source,span,6).map_err(|_|at(Error::InvalidValue,span.start))?;
220	        let expected=if kind==b"rgba"{4}else{6}; if spans.len()!=expected{return Err(at(Error::InvalidValue,span.start));}
221	        for component in spans {let n=number(source,component).map_err(|_|at(Error::InvalidValue,component.start))?; if kind==b"rgba"&&!(0.0..=1.0).contains(&n){return Err(at(Error::InvalidValue,component.start));}}
222	        return Ok(())
223	    }
224	    Err(at(Error::InvalidValue,span.start))
225	}
226	fn validate_item_fields(fields:&[Field],with_label:&[&[u8]],without_label:&[&[u8]],span:Span)->Result<()> {
227	    let allowed=if field(fields,b"label").is_some(){with_label}else{without_label};require_fields(fields,allowed,span.start)
228	}
229	fn require_track_fields(fields:&[Field],name:bool,drawing:bool,span:Span)->Result<()> {
230	    if drawing {if name {require_fields(fields,&[b"id",b"kind",b"target",b"name",b"visible",b"cels"],span.start)}else{require_fields(fields,&[b"id",b"kind",b"target",b"visible",b"cels"],span.start)}}
231	    else if name {require_fields(fields,&[b"id",b"kind",b"target",b"name",b"visible",b"property",b"value_type",b"interpolation",b"keys"],span.start)}
232	    else {require_fields(fields,&[b"id",b"kind",b"target",b"visible",b"property",b"value_type",b"interpolation",b"keys"],span.start)}
233	}
234	fn required<'a>(fields:&'a[Field],key:&[u8])->Option<&'a Field>{field(fields,key)}
235	pub(crate) fn field<'a>(fields:&'a[Field],key:&[u8])->Option<&'a Field>{fields.iter().find(|f|f.key==key)}
236	fn require_fields(fields:&[Field],names:&[&[u8]],offset:usize)->Result<()> {
237	    if fields.len()!=names.len()||fields.iter().any(|f|!names.contains(&f.key.as_slice())){return Err(at(Error::InvalidSchema,offset));} Ok(())
238	}
239	pub(crate) fn string(source:&[u8],span:Span)->Result<Vec<u8>> {
240	    let bytes=source.get(span.start..span.end).ok_or_else(||at(Error::InvalidValue,span.start))?;
241	    if bytes.len()<2||bytes[0]!=b'"'||bytes[bytes.len()-1]!=b'"'{return Err(at(Error::MalformedJson,span.start));}
242	    decode_string(&bytes[1..bytes.len()-1]).ok_or_else(||at(Error::Limit,span.start))
243	}
244	pub(crate) fn uint(source:&[u8],span:Span)->Result<u32>{
245	    let bytes=source.get(span.start..span.end).ok_or_else(||at(Error::InvalidValue,span.start))?;
246	    if bytes.is_empty()||!bytes.iter().all(u8::is_ascii_digit){return Err(at(Error::InvalidValue,span.start));}
247	    let mut value=0u32;for b in bytes {value=value.checked_mul(10).and_then(|v|v.checked_add(u32::from(*b-b'0'))).ok_or_else(||at(Error::Limit,span.start))?;}Ok(value)
248	}
249	pub(crate) fn boolean(source:&[u8],span:Span)->Result<bool>{match source.get(span.start..span.end){Some(b"true")=>Ok(true),Some(b"false")=>Ok(false),_=>Err(at(Error::InvalidValue,span.start))}}
250	fn number(source:&[u8],span:Span)->Result<f64>{let raw=source.get(span.start..span.end).ok_or_else(||at(Error::InvalidValue,span.start))?;let s=std::str::from_utf8(raw).map_err(|_|at(Error::InvalidValue,span.start))?;let n=s.parse::<f64>().map_err(|_|at(Error::InvalidValue,span.start))?;if n.is_finite(){Ok(n)}else{Err(at(Error::InvalidValue,span.start))}}
251	fn at(error:Error,offset:usize)->DecodeFailure{DecodeFailure{error,offset,canceled:false}}
