255	    pub fn track_at(&self,index:usize)->Option<TrackView<'a>>{access::track_at(self,index)}
256	    pub fn item_at(&self,track:usize,index:usize)->Option<ItemView<'a>>{access::item_at(self,track,index)}
257	    pub fn item_next(&self,track:usize,it:&mut TimelineIterator)->Option<ItemView<'a>>{access::item_next(self,track,it)}
258	    pub fn track_count(&self)->usize{self.tracks.len()}
259	    pub fn source(&self)->&'a [u8]{self.source}
260	    pub fn tracks_span(&self)->Span{self.tracks_span}
261	    pub fn ticks_per_second(&self)->u32{self.ticks_per_second}
262	    pub fn duration_ticks(&self)->u32{self.duration_ticks}
263	    pub fn fps(&self)->(u32,u32){(self.fps_numerator,self.fps_denominator)}
264	    pub fn loop_mode(&self)->LoopMode{self.loop_mode}
265	    pub fn onion(&self)->(u32,u32,f64){(self.onion_before,self.onion_after,self.onion_opacity)}
