  5	pub(crate) fn track_at<'a>(view:&TimelineView<'a>,index:usize)->Option<TrackView<'a>> {
  6	    let meta=*view.tracks.get(index)?; let fields=object_fields(view.source,meta.span).ok()?;
  7	    let id=raw_string(view.source,field(&fields,b"id")?.value)?;
  8	    let kind=raw_string(view.source,field(&fields,b"kind")?.value)?;
  9	    let target=raw_string(view.source,field(&fields,b"target")?.value)?;
 10	    let visible=boolean(view.source,field(&fields,b"visible")?.value).ok()?;
 11	    let name=field(&fields,b"name").and_then(|f|raw_string(view.source,f.value));
 12	    let (property,value_type,interpolation)=if meta.drawing {(None,None,None)} else {
 13	        (Some(raw_string(view.source,field(&fields,b"property")?.value)?),
 14	         Some(raw_string(view.source,field(&fields,b"value_type")?.value)?),
 15	         Some(raw_string(view.source,field(&fields,b"interpolation")?.value)?))
 16	    };
 17	    Some(TrackView {id,kind,target,name,visible,payload_json:view.source.get(meta.span.start..meta.span.end)?,item_count:meta.item_count,property,value_type,interpolation})
 18	}
