 20	pub(crate) fn item_at<'a>(view:&TimelineView<'a>,track:usize,index:usize)->Option<ItemView<'a>> {
 21	    let meta=*view.tracks.get(track)?; let mut reader=Reader::new(view.source,None); reader.cursor=meta.items.start;
 22	    reader.space().ok()?; if reader.source.get(reader.cursor)!=Some(&b'['){return None;} reader.cursor+=1; reader.space().ok()?;
 23	    for current in 0..=index {
 24	        let start=reader.cursor; if reader.source.get(start)==Some(&b']'){return None;}
 25	        reader.scan(1).ok()?; let span=Span{start,end:reader.cursor};
 26	        if current==index{return make_item(view.source,meta,span)}
 27	        reader.space().ok()?; if reader.source.get(reader.cursor)!=Some(&b','){return None;} reader.cursor+=1; reader.space().ok()?;
 28	    }
 29	    None
 30	}
