 32	pub(crate) fn item_next<'a>(view:&TimelineView<'a>,track:usize,it:&mut TimelineIterator)->Option<ItemView<'a>> {
 33	    let meta=*view.tracks.get(track)?;
 34	    if it.initialized&&it.track_index!=track{return None;}
 35	    if !it.initialized {
 36	        it.track_index=track; it.next_index=0; it.source_cursor=meta.items.start; it.initialized=true;
 37	        let mut reader=Reader::new(view.source,None); reader.cursor=it.source_cursor; reader.space().ok()?;
 38	        if reader.source.get(reader.cursor)!=Some(&b'['){return None;} reader.cursor+=1; reader.space().ok()?; it.source_cursor=reader.cursor;
 39	    }
 40	    if it.source_cursor==usize::MAX||it.source_cursor<meta.items.start||it.source_cursor>meta.items.end{return None;}
 41	    let mut reader=Reader::new(view.source,None); reader.cursor=it.source_cursor; reader.space().ok()?;
 42	    if reader.source.get(reader.cursor)==Some(&b']'){it.source_cursor=usize::MAX;return None;}
 43	    let start=reader.cursor; reader.scan(1).ok()?; let span=Span{start,end:reader.cursor}; reader.space().ok()?;
 44	    match reader.source.get(reader.cursor) {Some(b',')=>{reader.cursor+=1;reader.space().ok()?;it.source_cursor=reader.cursor;},Some(b']')=>{it.source_cursor=usize::MAX;},_=>return None}
 45	    it.next_index=it.next_index.checked_add(1)?;
 46	    make_item(view.source,meta,span)
 47	}
