 49	fn make_item<'a>(source:&'a[u8],meta:TrackMeta,span:Span)->Option<ItemView<'a>> {
 50	    let fields=object_fields(source,span).ok()?;
 51	    let tick=uint(source,field(&fields,b"tick")?.value).ok()?;
 52	    let (asset,value_json)=if meta.drawing {
 53	        (Some(raw_string(source,field(&fields,b"asset")?.value)?),None)
 54	    }else{
 55	        let value=field(&fields,b"value")?.value;
 56	        (None,Some(source.get(value.start..value.end)?))
 57	    };
 58	    Some(ItemView{tick,asset,value_json,source:span})
 59	}
