 26	void skip_space(json_reader *reader)
 27	{
 28	    if (!json_reader_poll_cancel(reader)) return;
 29	    while (reader->cursor < reader->source.len &&
 30	           is_space(reader->source.ptr[reader->cursor])) {
 31	        reader->cursor++;
