 36	bool json_reader_poll_cancel(json_reader *reader)
 37	{
 38	    if (reader->canceled || reader->cancel_check == NULL || reader->cursor == 0U ||
 39	        (reader->cursor & 4095U) != 0U) return !reader->canceled;
 40	    if (reader->cancel_check(reader->cancel_context)) {
 41	        reader->canceled = true;
 42	        reader->error = reader->cursor;
 43	        reader->error_kind = PROJECT_TIMELINE_INVALID_ARGUMENT;
 44	        return false;
 45	    }
 46	    return true;
 47	}
