 63	static bool utf8_sequence(const uint8_t *bytes, size_t length, size_t *cursor)
 64	{
 65	    uint8_t first = bytes[*cursor];
 66	    size_t width = first >= 0xc2U && first <= 0xdfU ? 2U :
 67	        first >= 0xe0U && first <= 0xefU ? 3U :
 68	        first >= 0xf0U && first <= 0xf4U ? 4U : 0U;
 69	    if (width == 0U || width > length - *cursor) return false;
 70	    uint8_t second = bytes[*cursor + 1U];
 71	    if ((second & 0xc0U) != 0x80U ||
 72	        (first == 0xe0U && second < 0xa0U) ||
 73	        (first == 0xedU && second >= 0xa0U) ||
 74	        (first == 0xf0U && second < 0x90U) ||
 75	        (first == 0xf4U && second >= 0x90U)) return false;
 76	    for (size_t i = 2U; i < width; i++)
 77	        if ((bytes[*cursor + i] & 0xc0U) != 0x80U) return false;
 78	    *cursor += width;
 79	    return true;
 80	}
