 82	static int hex_value(uint8_t byte)
 83	{
 84	    if (byte >= '0' && byte <= '9') return (int)(byte - '0');
 85	    if (byte >= 'a' && byte <= 'f') return (int)(byte - 'a') + 10;
 86	    if (byte >= 'A' && byte <= 'F') return (int)(byte - 'A') + 10;
 87	    return -1;
 88	}
