246	bool scan_number(json_reader *reader)
247	{
248	    size_t start = reader->cursor;
249	    if (reader->source.ptr[reader->cursor] == '-') reader->cursor++;
250	    if (reader->cursor >= reader->source.len) return fail(reader, PROJECT_TIMELINE_MALFORMED_JSON);
251	    if (reader->source.ptr[reader->cursor] == '0') reader->cursor++;
252	    else {
253	        if (reader->source.ptr[reader->cursor] < '1' || reader->source.ptr[reader->cursor] > '9')
254	            return fail(reader, PROJECT_TIMELINE_MALFORMED_JSON);
255	        while (reader->cursor < reader->source.len && reader->source.ptr[reader->cursor] >= '0' &&
256	               reader->source.ptr[reader->cursor] <= '9') reader->cursor++;
257	    }
258	    if (reader->cursor < reader->source.len && reader->source.ptr[reader->cursor] == '.') {
259	        reader->cursor++;
260	        size_t digits = reader->cursor;
261	        while (reader->cursor < reader->source.len && reader->source.ptr[reader->cursor] >= '0' &&
262	               reader->source.ptr[reader->cursor] <= '9') reader->cursor++;
263	        if (reader->cursor == digits) return fail(reader, PROJECT_TIMELINE_MALFORMED_JSON);
264	    }
265	    if (reader->cursor < reader->source.len &&
266	        (reader->source.ptr[reader->cursor] == 'e' || reader->source.ptr[reader->cursor] == 'E')) {
267	        reader->cursor++;
268	        if (reader->cursor < reader->source.len &&
269	            (reader->source.ptr[reader->cursor] == '+' || reader->source.ptr[reader->cursor] == '-'))
270	            reader->cursor++;
271	        size_t digits = reader->cursor;
272	        while (reader->cursor < reader->source.len && reader->source.ptr[reader->cursor] >= '0' &&
273	               reader->source.ptr[reader->cursor] <= '9') reader->cursor++;
274	        if (reader->cursor == digits) return fail(reader, PROJECT_TIMELINE_MALFORMED_JSON);
275	    }
276	    if (reader->cursor - start > 96U) return fail(reader, PROJECT_TIMELINE_LIMIT);
277	    char buffer[97];
278	    size_t length = reader->cursor - start;
279	    memcpy(buffer, reader->source.ptr + start, length);
280	    buffer[length] = '\0';
281	    char *end = NULL;
282	    (void)pthread_once(&timeline_locale_once, initialize_timeline_locale);
283	    if (timeline_c_locale == (locale_t)0) return fail(reader, PROJECT_TIMELINE_INVALID_VALUE);
284	    double value = strtod_l(buffer, &end, timeline_c_locale);
285	    if (end != buffer + length || !isfinite(value)) return fail(reader, PROJECT_TIMELINE_INVALID_VALUE);
286	    return true;
287	}
