291	static bool scan_array(json_reader *reader, unsigned depth)
292	{
293	    reader->cursor++;
294	    skip_space(reader);
295	    if (reader->cursor < reader->source.len && reader->source.ptr[reader->cursor] == ']') {
296	        reader->cursor++;
297	        return true;
298	    }
299	    for (;;) {
300	        if (!scan_value(reader, depth + 1U)) return false;
301	        skip_space(reader);
302	        if (reader->cursor >= reader->source.len) return fail(reader, PROJECT_TIMELINE_MALFORMED_JSON);
303	        uint8_t byte = reader->source.ptr[reader->cursor++];
304	        if (byte == ']') return true;
305	        if (byte != ',') return fail(reader, PROJECT_TIMELINE_MALFORMED_JSON);
306	        skip_space(reader);
307	    }
308	}
