310	static bool scan_object(json_reader *reader, unsigned depth)
311	{
312	    reader->cursor++;
313	    base_bytes keys[TIMELINE_MAX_FIELDS];
314	    size_t key_count = 0U;
315	    skip_space(reader);
316	    if (reader->cursor < reader->source.len && reader->source.ptr[reader->cursor] == '}') {
317	        reader->cursor++;
318	        return true;
319	    }
320	    for (;;) {
321	        size_t key_offset = reader->cursor;
322	        base_bytes key;
323	        if (!scan_string(reader, &key)) return false;
324	        for (size_t i = 0U; i < key_count; i++) {
325	            if (json_strings_equal(keys[i], key)) {
326	                reader->cursor = key_offset;
327	                return fail(reader, PROJECT_TIMELINE_DUPLICATE);
328	            }
329	        }
330	        if (key_count >= TIMELINE_MAX_FIELDS) return fail(reader, PROJECT_TIMELINE_LIMIT);
331	        keys[key_count++] = key;
332	        skip_space(reader);
333	        if (reader->cursor >= reader->source.len || reader->source.ptr[reader->cursor++] != ':')
334	            return fail(reader, PROJECT_TIMELINE_MALFORMED_JSON);
335	        if (!scan_value(reader, depth + 1U)) return false;
336	        skip_space(reader);
337	        if (reader->cursor >= reader->source.len) return fail(reader, PROJECT_TIMELINE_MALFORMED_JSON);
338	        uint8_t byte = reader->source.ptr[reader->cursor++];
339	        if (byte == '}') return true;
340	        if (byte != ',') return fail(reader, PROJECT_TIMELINE_MALFORMED_JSON);
341	        skip_space(reader);
342	    }
343	}
