345	bool scan_value(json_reader *reader, unsigned depth)
346	{
347	    if (depth > 32U) return fail(reader, PROJECT_TIMELINE_LIMIT);
348	    skip_space(reader);
349	    if (reader->cursor >= reader->source.len) return fail(reader, PROJECT_TIMELINE_MALFORMED_JSON);
350	    uint8_t byte = reader->source.ptr[reader->cursor];
351	    if (byte == '"') return scan_string(reader, NULL);
352	    if (byte == '{') return scan_object(reader, depth);
353	    if (byte == '[') return scan_array(reader, depth);
354	    if (byte == '-' || (byte >= '0' && byte <= '9')) return scan_number(reader);
355	    static const char *const literals[] = {"true", "false", "null"};
356	    for (size_t i = 0U; i < sizeof(literals) / sizeof(literals[0]); i++) {
357	        size_t n = strlen(literals[i]);
358	        if (reader->source.len - reader->cursor >= n &&
359	            memcmp(reader->source.ptr + reader->cursor, literals[i], n) == 0) {
360	            reader->cursor += n;
361	            return true;
362	        }
363	    }
364	    return fail(reader, PROJECT_TIMELINE_MALFORMED_JSON);
365	}
