342	        if (!parse_object_fields(&reader, track_spans[ti], &track)) return result(reader.error_kind, reader.error);
343	        const json_field *kind_field = get_field(&track, "kind");
344	        base_bytes kind;
345	        if (kind_field == NULL || !span_string(&reader, kind_field->value, &kind)) return result(PROJECT_TIMELINE_INVALID_SCHEMA, track_spans[ti].start);
346	        bool drawing = json_string_equal(kind, "drawing");
