351	        char id_storage[129], target_storage[257];
352	        size_t id_length = 0U, target_length = 0U;
353	        base_bytes id, target;
354	        bool visible = false;
355	        const json_field *id_field = get_field(&track, "id"), *target_field = get_field(&track, "target");
