410	                 json_string_equal(property, "cx") || json_string_equal(property, "cy") ||
411	                 json_string_equal(property, "r") || json_string_equal(property, "rx") ||
412	                 json_string_equal(property, "ry") || json_string_equal(property, "opacity") ||
413	                 json_string_equal(property, "fill-opacity") || json_string_equal(property, "stroke-opacity") ||
414	                 json_string_equal(property, "stroke-width") || json_string_equal(property, "stroke-dashoffset")) &&
