558	{
559	    if (view == NULL || iterator == NULL || out_item == NULL || track_index >= view->track_count ||
560	        view->track_count > PROJECT_TIMELINE_MAX_TRACKS ||
561	        !base_bytes_valid(view->item_spans[track_index])) return false;
562	    if (iterator->initialized && iterator->track_index != track_index) return false;
563	    size_t array_start = (size_t)(view->item_spans[track_index].ptr - view->source.ptr);
564	    size_t array_end = array_start + view->item_spans[track_index].len;
565	    if (!iterator->initialized) {
566	        iterator->track_index = track_index;
567	        iterator->next_index = 0U;
568	        iterator->source_cursor = array_start;
569	        iterator->initialized = true;
570	    }
571	    if (iterator->source_cursor < array_start || iterator->source_cursor > array_end ||
572	        iterator->source_cursor == SIZE_MAX) return false;
573	    json_reader reader = {.source = view->source, .cursor = iterator->source_cursor,
574	        .error_kind = PROJECT_TIMELINE_OK};
575	    json_span item_span;
576	    if (iterator->next_index == 0U) {
577	        reader.cursor = array_start;
578	        skip_space(&reader);
579	        if (reader.cursor >= reader.source.len || reader.source.ptr[reader.cursor++] != '[') return false;
580	        skip_space(&reader);
581	    }
582	    size_t start = reader.cursor;
583	    if (reader.cursor >= reader.source.len || reader.source.ptr[reader.cursor] == ']') return false;
584	    if (!scan_value(&reader, 1U)) return false;
585	    item_span = (json_span){start, reader.cursor};
586	    skip_space(&reader);
587	    if (reader.cursor >= reader.source.len) return false;
588	    uint8_t delimiter = reader.source.ptr[reader.cursor++];
589	    if (delimiter != ',' && delimiter != ']') return false;
590	    if (delimiter == ',') skip_space(&reader);
591	    iterator->source_cursor = delimiter == ']' ? SIZE_MAX : reader.cursor;
592	    object_fields item;
593	    if (!parse_object_fields(&reader, item_span, &item)) return false;
594	    const json_field *tick_field = get_field(&item, "tick");
595	    uint32_t tick = 0U;
596	    if (tick_field == NULL || !span_uint(&reader, tick_field->value, &tick)) return false;
597	    project_timeline_item_view output = {tick, {NULL, 0U}, {NULL, 0U},
598	        item_span.start, item_span.end - item_span.start};
599	    if (view->drawing_tracks[track_index]) {
600	        const json_field *asset = get_field(&item, "asset");
601	        if (asset == NULL || !span_string(&reader, asset->value, &output.asset)) return false;
602	    } else {
