213	project_timeline_result project_timeline_decode_cancellable(base_bytes source,
214	    const project_timeline_context *context, project_timeline_view *out_view,
215	    bool (*cancel_check)(void *), void *cancel_context, bool *out_canceled)
216	{
217	    if (out_canceled != NULL) *out_canceled = false;
218	    if (out_view == NULL || !base_bytes_valid(source) || context == NULL ||
219	        (context->scene_ids == NULL && context->scene_id_count != 0U) ||
220	        (context->assets == NULL && context->asset_count != 0U))
221	        return result(PROJECT_TIMELINE_INVALID_ARGUMENT, 0U);
222	    memset(out_view, 0, sizeof(*out_view));
223	    if (context->scene_id_count > 1000000U || context->asset_count > PROJECT_BUNDLE_MAX_ASSET_COUNT)
224	        return result(PROJECT_TIMELINE_LIMIT, 0U);
225	    for (size_t i = 0U; i < context->scene_id_count; i++) {
226	        if (!base_bytes_valid(context->scene_ids[i]) || context->scene_ids[i].len == 0U ||
227	            context->scene_ids[i].len > 256U) return result(PROJECT_TIMELINE_INVALID_ARGUMENT, 0U);
228	        if (i > 0U) {
229	            int order = bytes_compare(context->scene_ids[i - 1U], context->scene_ids[i]);
230	            if (order == 0) return result(PROJECT_TIMELINE_DUPLICATE, 0U);
231	            if (order > 0) return result(PROJECT_TIMELINE_INVALID_ARGUMENT, 0U);
232	        }
233	    }
234	    for (size_t i = 0U; i < context->asset_count; i++) {
235	        if (!valid_asset_name(context->assets[i].name) ||
236	            !valid_media_type(context->assets[i].media_type))
237	            return result(PROJECT_TIMELINE_INVALID_ARGUMENT, 0U);
238	        for (size_t prior = 0U; prior < i; prior++)
239	            if (bytes_equal(context->assets[prior].name, context->assets[i].name))
240	                return result(PROJECT_TIMELINE_DUPLICATE, 0U);
241	    }
242	    if (source.len == 0U) { out_view->empty = true; return result(PROJECT_TIMELINE_OK, 0U); }
243	    if (source.len > PROJECT_BUNDLE_MAX_TIMELINE_BYTES)
244	        return result(PROJECT_TIMELINE_LIMIT, 0U);
245	
246	    json_reader reader = {.source = source, .error_kind = PROJECT_TIMELINE_OK,
