248	    size_t root_start = 0U;
249	    if (!scan_value(&reader, 0U)) {
250	        if (out_canceled != NULL) *out_canceled = reader.canceled;
251	        return result(reader.error_kind, reader.error);
252	    }
253	    root_start = reader.cursor;
254	    skip_space(&reader);
255	    if (reader.cursor != source.len) return result(PROJECT_TIMELINE_MALFORMED_JSON, reader.cursor);
256	    object_fields root;
257	    if (!parse_object_fields(&reader, (json_span){0U, root_start}, &root))
258	        return result(reader.error_kind, reader.error);
259	    const char *const root_names[] = {"schema", "version", "ticks_per_second", "duration_ticks", "fps", "loop", "onion", "tracks"};
260	    base_bytes schema;
261	    uint32_t version, tps, duration;
262	    const json_field *f_schema = get_field(&root, "schema");
263	    const json_field *f_version = get_field(&root, "version");
264	    if (f_schema == NULL)
265	        return result(PROJECT_TIMELINE_UNSUPPORTED_VERSION, 0U);
266	    if (!span_string(&reader, f_schema->value, &schema))
267	        return result(PROJECT_TIMELINE_INVALID_SCHEMA, reader.error);
268	    if (!json_string_equal(schema, "vexel.animation")) return result(PROJECT_TIMELINE_UNSUPPORTED_VERSION, f_schema->value.start);
269	    if (f_version == NULL) return result(PROJECT_TIMELINE_INVALID_SCHEMA, f_schema->value.start);
270	    if (!span_uint(&reader, f_version->value, &version)) return result(reader.error_kind, reader.error);
