   114	static bool decode_string_content(base_bytes encoded, base_mut_bytes output,
   115	                                  size_t *out_length, bool *out_limit)
   116	{
   117	    if (!base_bytes_valid(encoded) || (output.ptr == NULL && output.len != 0U) || out_length == NULL)
   118	        return false;
   119	    size_t input = 0U, length = 0U;
   120	    if (out_limit != NULL) *out_limit = false;
   121	    while (input < encoded.len) {
   122	        uint8_t byte = encoded.ptr[input++];
   123	        uint32_t codepoint = byte;
   124	        if (byte == '\\') {
   125	            if (input >= encoded.len) return false;
   126	            uint8_t escaped = encoded.ptr[input++];
   127	            if (escaped == '"' || escaped == '\\' || escaped == '/') codepoint = escaped;
   128	            else if (escaped == 'b') codepoint = 8U;
   129	            else if (escaped == 'f') codepoint = 12U;
   130	            else if (escaped == 'n') codepoint = 10U;
   131	            else if (escaped == 'r') codepoint = 13U;
   132	            else if (escaped == 't') codepoint = 9U;
   133	            else if (escaped == 'u') {
   134	                if (encoded.len - input < 4U) return false;
   135	                codepoint = 0U;
   136	                for (size_t i = 0U; i < 4U; i++) {
   137	                    int digit = hex_value(encoded.ptr[input++]);
   138	                    if (digit < 0) return false;
   139	                    codepoint = (codepoint << 4U) | (uint32_t)digit;
   140	                }
   141	                if (codepoint >= 0xd800U && codepoint <= 0xdbffU) {
   142	                    if (encoded.len - input < 6U || encoded.ptr[input++] != '\\' ||
   143	                        encoded.ptr[input++] != 'u') return false;
   144	                    uint32_t low = 0U;
   145	                    for (size_t i = 0U; i < 4U; i++) {
   146	                        int digit = hex_value(encoded.ptr[input++]);
   147	                        if (digit < 0) return false;
   148	                        low = (low << 4U) | (uint32_t)digit;
   149	                    }
   150	                    if (low < 0xdc00U || low > 0xdfffU) return false;
   151	                    codepoint = 0x10000U + ((codepoint - 0xd800U) << 10U) + (low - 0xdc00U);
   152	                } else if (codepoint >= 0xdc00U && codepoint <= 0xdfffU) return false;
   153	            } else return false;
   154	        } else if (byte >= 0x80U) {
   155	            input--;
   156	            size_t start = input;
   157	            if (!utf8_sequence(encoded.ptr, encoded.len, &input)) return false;
   158	            size_t width = input - start;
   159	            if (width > output.len - length) {
   160	                if (out_limit != NULL) *out_limit = true;
   161	                return false;
   162	            }
   163	            memcpy(output.ptr + length, encoded.ptr + start, width);
   164	            length += width;
   165	            continue;
   166	        } else if (byte < 0x20U) return false;
   167	        if (!append_utf8(codepoint, output, &length)) {
   168	            if (out_limit != NULL) *out_limit = true;
   169	            return false;
   170	        }
   171	        if (length > PROJECT_TIMELINE_MAX_STRING_BYTES) {
   172	            if (out_limit != NULL) *out_limit = true;
   173	            return false;
   174	        }
   175	    }
   176	    *out_length = length;
   177	    return true;
   178	}
