570	bool array_count(json_reader *reader, json_span span, size_t capacity,
571	                        size_t *out_count)
572	{
573	    json_reader child = *reader;
574	    child.cursor = span.start;
575	    skip_space(&child);
576	    if (child.cursor >= child.source.len || child.source.ptr[child.cursor++] != '[') {
577	        *reader = child; return fail(reader, PROJECT_TIMELINE_INVALID_SCHEMA);
578	    }
579	    size_t count = 0U;
580	    skip_space(&child);
581	    if (child.cursor < child.source.len && child.source.ptr[child.cursor] == ']') {
582	        child.cursor++;
