584	        if (count >= capacity) { *reader = child; return fail(reader, PROJECT_TIMELINE_LIMIT); }
585	        if (!scan_value(&child, 1U)) { *reader = child; return false; }
586	        count++;
587	        skip_space(&child);
588	        if (child.cursor >= child.source.len) { *reader = child; return fail(reader, PROJECT_TIMELINE_MALFORMED_JSON); }
589	        uint8_t byte = child.source.ptr[child.cursor++];
590	        if (byte == ']') break;
591	        if (byte != ',') { *reader = child; return fail(reader, PROJECT_TIMELINE_MALFORMED_JSON); }
592	        skip_space(&child);
593	    }
594	    if (child.cursor != span.end) { *reader = child; return fail(reader, PROJECT_TIMELINE_MALFORMED_JSON); }
595	    *out_count = count;
596	    return true;
597	}
